    badgeUnlock5: 'ዝያዳ ክብደት ብዛዕባ እቲ እትገብሮ ፦ ርእይቶ ወይ ግብረ መልሲ ናይ ሓደ ባጅ ሓላፊ ፡ ኣብ ሓደ ደረጃ ፡ ከም ናይ ምምሕዳር ድምጺ ፡ ሓደ ብዘይ ባጅ ፡ ክልተ ኣብ ክራብ ፡ ከምኡውን ኣብ ልዕሊኡ ኣብ ሜጋሎዶን ንዝርከቡ ኣርባዕተ ደረጃታት ዝያዳ ይቑጸር ። እዚ ኣብ ሓደ ግብረ መልሲኻ ብዙሕነት ዘለዎ እዩ ፣ ካልኣይ ድማ ፈጺሙ ኣይተርፍን እዩ ።',
    badgeDelegationTitle: 'ነቲ ባጅካ ልኢኽዎ',
    badgeDelegationDesc: 'ሓደ ባጅ ልቓሕ ክኸውን ይኽእል እዩ ። ነፍሲ ወከፍ ዝደለኻዮ ሩጫ ፡ ሓደ ኣብ ክራብ ፡ 13 ኣብ ሜጋሎዶን ፡ ካልእ ናይ ገዛእ ርእስኻ ደረጃ ሒዝካ ኽሳዕ እትወጽእ ፡ ሓደ ናይ ልኡኽ ቦታ ይህበካ ። እዚ ድማ ኣብ DeHub ዘሎ ጽልዋ ፡ ኣብ ክንዲ ኣብ ሓደ ቦርሳ ኮፍ ኢልካ ምስ ሓደ ጉጅለ ክትጓዓዝ ስለ ዝዓለመ እዩ ዘሎ ፡ ሰራሕተኛታት ፡ ጋንታታትን ካልኣይቲ ሕሳብን ፡ ብዘይ ዝኾነ ሰብ ምልክታት ከይንቀሳቐሱ ወይ ቁልፊ ከይሓልፍ ፡ ነቲ ደገፍኦም ይረኽቡ እዮም ።',
    badgeDelegationB1: 'ሓደ ዓይነት ደረጃ ፡ ሓደ ካብዞም ዝስዕቡ ኣይኮነን ።',
    badgeDelegationB1Desc: 'ሜጋሎዶን ንሜጋሎዶን ኣበጊሱ እዩ ። ሓደ ባጅ ነቲ እትእዝዞ ጽልዋ ይገልጽ ፡ ስለዚ እቶም ዝምለሱኻ ሰባት ነቲ እትሸከሞ ነገር ይገብሩ እዮም ።',
    badgeDelegationB2: 'ስሎታት ካብ ገዛእ ርእስኻ እዮም ዚመጹ ፦',
    badgeDelegationB2Desc: 'እቲ እተበደለ ባጅ ናይ ገዛእ ርእሱ ኣፈታትሓ የብሉን ፣ ስለዚ ናይ ልቓሕ ደረጃ ፈጺሙ ክበድእ ኣይክእልን እዩ ።',
    badgeDelegationB3: 'እዚ ድማ ከምዚ ዚስዕብ እዩ ፦',
    badgeDelegationB3Desc: 'ኣብ ዝኾነ ቦታ ኣብ ኣፕሊኬሽን ዝተወሃበ ባጅ ጠውቑ ፡ መን ከም ዝድግፎ ድማ ስም ኣለዎ ። ካብ ኣበይ ከም ዝመጸ ዚሕባእ ነገር የለን ።',
    badgeDelegationB4: 'ኣብ ዝኾነ እዋን ፡',
    badgeDelegationB5: 'ኩነታት ፡ መሰል የብሉን ፦',
    badgeDelegationB5Desc: 'ሓደ ናይ ልቓሕ ባጅ እቲ መድረኽ ዘርኢ እዩ ፣ ነቲ ምስ ደረጃ ዚኸይድ ክብደት ድማ ይሕዝ — እቲ ልቓሕ ዝነበረ ደረጃ ፡ ርእይቶ ወይ ግብረ መልሲ ይቑጸር እዩ ። እቲ ዘይሸከሞ ነገር ብገንዘብ ዝተኸፍለ ነገር እዩ ፦ ናይ ክፍሊት ደረጃኻ ፣ ናይ ምልክት መግዛእቲ ቅናሽካ ፣ ናይ ዕለታዊ ናይ ልኡኽ ድጎማኻን ናይ ገዛእ ርእስኻ ልኡኽ ኣፈፃፅማታትካን ገና ካብ ገዛእ ርእስኻ እትሕዝዎ ክፋል ይነበብ ኣሎ ።',
    badgeDelegationB6: 'ነቲ እተቐበሎ ተመሳሳሊ በረኸት ። *',
    badgeDelegationB6Desc: 'ሓደ ኣፈፃፅማ ነቲ ዝለዓለ ደረጃኻ ክህበካ ኣየድልዮን እዩ ። ነቲ ዘይዕጸወ ዕንጨይቲ ሕረዶ ፡ ሓደ ሰብ ድማ ብዘይ ሜጋሎዶን ኣብ ንጉስ ኮብራ ንድሕሪት ተመሊስካ ።',
    badgeDelegationB7: 'እዚ ድማ ከምዚ ዚስዕብ እዩ ፦',
    badgeDelegationB7Desc: 'እቲ ናብ መለያ ዝቐረበ ባጅ ኣብ ናይ ኣፍልጦ ደወልኡ ይርአ ፣ ክኽሕዶ ይኽእል እዩ ። ሓደ ኻባኻትኩም ድሕሪኡ ሓደ ልኡኽ ኪውዳእ ይኽእል እዩ ።',
    tipTitle: 'ንፍቕሪኻ ኣስተማቕሮ',
    tipDesc1: 'ኣብ ኩሉ ሰቀላታትን ህያው ዥረታትን ዝተኣሳሰረ ኣገልግሎትና 10% ጥራይ እዩ ዝመጽእ ፣ እዚ ድማ ምስቲ ንቡር 60% ናይ ቲክቶክን ካልኦት መራሕቲ ኢንዱስትሪን ክኽፈል ከሎ ፣ ከምኡ\'ውን ኣብ ናይ ቪድዮ ስረዛታት ድምጺ ክህብ ይኽእል እዩ ፣ እዚ ድማ ነቲ ሓይሊ ናብ ኢድ ተመልካቲ ዘመልክት እዩ ።',
    tipDesc2: 'ንተዓዘብቲ ዝቕበሉ ምኽርታትን ምኽርታትን ኣብ ዝተፈላለዩ መራሕቲ ቦርዶታት ከምኡ\'ውን ኣብ ኣታዊታት ኣክሲዮናት ዝውስኑ ተዓዘብቲ ቆጸራትን ተመዝጋቢታትን ተመዝጊቦም ኣለዉ ። እቶም ተሳተፍቲ ናይ DeHub ምልክታት ነቲ ናይ ሓፈሻዊ ፕሮቶኮል ረብሓ ሚዛናዊ ኣክሲዮኖም ይረኽቡ እዮም ።',
    mineSubtitle: 'ዲክታላይዜሽን ሚዛናዊ ምህርቲን ናይ ኣታዊ ኣክሲዮን ሞዴል',
    mineDesc1: 'ገለ ጥራይ እዮም ልዕሊ 50 ሚልዮን DeHub ምልክታት ዝሕዝዎ ፣ መብዛሕትኦም ድማ ናይ ስራሕ ቦርሳታት እዮም ፣ እቶም ዝተረፉ ድማ ኣባላት ማሕበረሰብ እዮም ።',
    mineDesc2: 'እቲ ቀንዲ ጋንታ ወይ ናይ ላዕለዋይ ደረጃ ባጅ ዘለዎም ጥራይ እዮም ነቲ ዝተኣሳሰረ NFT ብምቃጸል ቪድዮ ብኡብኡ ክስወሩ ዝኽእሉ ። ድሕሪኡ ፡ እቲ ዝተፈጥረ ኩሉ ኣታዊታት ኣፕልትን ዝኾነ ይኹን ምስ ኩሎም ናይ ድምጺ ቦርሳታት ብምትሕብባር ፡ ነቲ ሕማቕ ተዋሳእቲ ንምግታእን ንተሳትፎ ማሕበረሰብ ንምትብባዕን ክካፈል እዩ ።',
    mineDynamic: 'እቲ ንኹሉ ጥቕሚ ዘድሊ ናይ DeHub ምልክታት መጠን ተለዋዋጭ ስለዝኾነ ኣብ ዝኾነ እዋን ምስ ዋጋ ክለዋወጥ ኣለዎ ። ዝኾነ ለውጢ ኣብ ኩሉ ወግዓዊ ቻነላት ብወግዒ ክግለጽ እዩ ።',
    govTitle: 'ምምሕዳር + ሚዛናዊ ስርዓት ዲዛይን',
    govDesc: 'እቲ ሰፊሕ ስርዓተ ምሕደራን ሚዛናዊነትን ፍትሓዊ ፡ ግሉጽ ፡ ብማሕበረሰብ ዝመርሕ መድረኽ ይፈጥር ፡ እዚ ድማ ማእከላይ ምቁጽጻር ይከላኸል ፡ ብምርግጋጽ ቁጠባዊ መደረታትን ዘመናዊ ሜካኒካትን ድማ ናይ ጥዕነት ደረጃታት ይዕቅብ ።',
    tokenUtilityDesign: 'ንድፊ ኣጠቃቀም ቶከን',
    tokenUtilityDesc: 'ብኻልእ ኣበሃህላ ፡ DeHub Tookens ፡ ናይ መበቆል ኣመራርሓና ምልክት ፡ ነዚ ዝስዕብ ግደታት ይፍቅድ ፦',
    tokenUtilityRole1: 'ሚዛናዊ ስክሪፕት',
    tokenUtilityRole2: 'ናይ ትሕዝቶ ግጭታትን ናይ መድረኽ ስርዓታትን ድምጺ ምሃብ',
    tokenUtilityRole3: 'ኣሰራርሓን ምትብባዕን ትሕዝቶ',
    keyPrinciple: 'ዝያዳ ምልክታት = ዝያዳ ጽልዋ ፡ ግን ዘይተመርመር ሓይሊ ጽልዋ ኣለዎ ።',
    quadraticDesc: 'ንመንግስቲ ዊል ንምቕናስ ፡',
    quadratic1: 'ኣርባዕተ ድምጺ ንዋና ሚዛናዊ ውሳነታት ንጥቀም ኢና ።',
    quadratic2: 'ኣብነት ፦ ናይ ድምጺ ሓይሊ = √(ቶከንስ ተቛሪጹ)',
    quadratic3: 'ስለዚ 100 ቶከንስ = 10 ድምጺ ፣ 10,000 ቶከንስ = 100 ድምጺ (10,000 ድምጺ ኣይኮነን) ።',
    modStakingPools: 'መዐቀኒ መዐቀኒታት',
