    modStaking2: 'ነፍሲ ወከፍ ዝተቐየረ ትሕዝቶ ናብ ማእከላይ መስመር ይኣቱ ።',
    modStaking3: 'እቶም ሰራሕተኛታት ነቲ ውጽኢት (እገዳ ፣ መጠንቀቕታ ፣ ዘይምርግጋእ ፣ ወዘተ) ይመርጹ ።',
    modStaking4: 'ቅኑዕ ድምጺ (ብመወዳእታ ውጽኢት) ዓስቢ ይረክብ ፣ ጌጋ ድምጺ ድማ ናብ ምቅልጣፍ ክመርሕ ይኽእል እዩ ።',
