    harpoon: '9) ሃርፖን',
    harpoonDesc: 'ብዛዕባ ሓደ ቦታ እትመርጽዎ ናይ ባጅ ደረጃታት ንነፍሲ ወከፍ ሓላፊ ኣፍልጦ ሃቦ ። ኣብ ትግራይ ሻርክ ተኸፊቱ ። ሕጂ ህያው ኩን ።',
    superPowersMore2: 'ኩሎም 12 ሓይልታት ኣብ ኣፕሊኬሽን ህያዋን ኮይኖም ተዘርዚሮም ኣለዉ ። ርእይቶኻ ኣብ ላዕሊ ናይ ካልእ ሰብ ክር ይሕዝ ። Signal Flare ንኹሉ ዝስዕብ መለያታት ሓደ ኣፍልጦ ይልእኽ ። ፍላክ ጃኬት ፡ ኣብ እዋን ስርሑ ፡ ናይ መቓብር መከላኸሊ ይገብር ። እቲ ጉጅለ ክሳብ ሸሞንተ መለያታት ናይ ቦርሳ ሓይሎም ዘራኽብ ስለ ዝኾነ ፡ ነፍሲ ወከፍ ኣባል ነቲ ዝተዋሃበ ሚዛኑ ይኽፍት ። Front Row ነቲ ኣብ ላዕሊ ዘሎ ደረጃ ባቡር ትቕበልዎ ዘለኹም ደረጃ የቕርቦ ። ጥልቀት ዘለዎ ህሉው ፡ ሓደ ኻብቲ ንፖስታ ኻልእ ሰብ ዚገብሮ ምትብባዕ ይህበካ ።',
