    settingsB7Desc: 'ናይ ብዙሕ ፖስታ መለያታትካ ፣ ናይ ሶላና ቦርሳኻ ፣ ናይ ቀዋሚ ፍሰት ቁልፊኻ ፣ ናይ ባዮሜትሪክ ክፉት ፣ ናይ ተጠቀምቲ ስምን ፍራክሽንን ፣ ከምኡ\'ውን ኣብ ቅኑዕ ቦታ ዝወድቕካ ኣቀማምጣታት ይደሊ ።',
    spDescTeamUp: 'ናይ ቦርሳ ሓይሊ ምስ ካልኦት ሸውዓተ ሕሳብ ብምትእስሳር ። ኣብ ውሽጢ እቲ ጉጅለ ዘሎ ኩሉ ሰብ ነቲ ዝተኣሳሰረ ሚዛን ይኽፍት ፡ ዋጋ የብሉን ። ሓደ ጉጅለ ብሕታዊ ክኸውን ይኽእል እዩ ፣ ስለዚ ሰባት ክቀላቀሉ ይሓትቱ ፣ እቲ ገዛኢ ድማ ይጽድቖም ።',
    stagesB3Desc: 'ሓደ ህያው ትራንስክሪፕት ስካነር ነቲ ክፍሊ ከምቲ ዝፍጸም ይሕዝ ፡ ብዘይ ማይክሮፎን ድማ ክትሳተፍ ይሕግዘካ ።',
    storesB4Desc: 'ኣብ መደበርካ ናይ ሕትመት-ን-ን-ምኽሪ ንግዲ ኣዘርጊሕካ ፡ ዝርዝር መደብርን ዝተኣሳሰረ ርክባትን ናብ ሓደ ቦታ ኣክሊልካ ፡ ኣብኡ ድማ ኣብ ቦርድ መደብርካ ተራእዩ ኣሎ ።',
    streamCreation1: 'ካብ ጸሓፍቲ ህያው',
    streamCreation2: 'ናይ ምስሊ መግለጺ ናይ ምስሊ መግለጺ',
    superPowersTitle: 'ኣብዝኤልናስ ኣብዝኤልናስ።',
    supportedTokensDesc: 'ምኽርታት ፣ ህያባትን መኽፈቲን ኣብ DeHub ምልክታት ይቐርቡ ፣ ግን ካብ ካልኦት ሚዛን ክትከፍሉ ትኽእሉ ኢኹም — USDC ፣ ETH ወይ ምልክታት ኣብ መሰረት ፣ BNB ሰንሰለት ፣ ሮቢንሃውድ ሰንሰለት ወይ ኣርክ — ንሳቶም ድማ ንዓኻ ተቐይሮም እዮም ።',
    tipDesc3: 'ምኽርታት ኣብ ልኡኽታት ፡ ርእይቶታት ፡ ቀጥታዊ መልእኽታትን ህያው ጅረታትን ይሰርሑ ። ናይ DeHub ምልክታት እንተ ዘይብልካ ፡ እቲ ናይ ጫፍ ወረቐት ካልኦት ሚዛናትካ የቕርብ — USDC, ETH ወይ ምልክታት ኣብ መሰረት ፡ BNB ሰንሰለት ፡ Robinhood Chain ወይ Arc — ቅድሚ እቲ ጫፍ ምውጻእካ ድማ ንዓኻ ይልወጥ ። ሓደ ጽሑፍ ምስ ኣጥፊእካ ፡ እቲ ጠውቑር ጠውቑ ፡ ነቲ ኣቐዲምካ እተዋህበካ ቦታ ምእንቲ ኽትርኢ ፡ ዜደንቕ ኣልማዝ የርኢ ።',
