    intro: 'DeHub ምልክታት ናይ DeHub ኔትወርክ ናይ መበቆል ናይ ጥቕሚ ምንቅስቓስ እዮም ፤ DHB ናይ ምልክት ምልክትኦም እዩ ። እዚኦም ኣብ ነፍሲ ወከፍ d\'app ናይ መለያ ኣሃዱ እዮም — እቲ እትጥቀመሉ ነገር ፡ ትሕዝቶኻ ትኸፍት ፡ ክትርእዮን ክትፈጥርን ትረኽቦ ፡ ኣብ ወለዶ AI ድማ ትውፍዮ ። ኣብ ሓደ እዋን ስለ ዝነብሩ ፡ ኣብ ክንዲ ኣብ ሓደ ናይ ውልቀ-መቐመጢ መቐመጢ ኮፍ ኢልካ ፡ ኣብ ስነ-ምህዳር ዘሎ ኩሉ ምንቅስቓስ ዋጋ ብወግዒ ክረጋገጽ ይኽእል እዩ ።',
