    howItWorksDesc1: 'ነፍሲ ወከፍ ናይ DeHub ሕሳብ ኣብ ውሽጢ ዝተሃንጸ ቦርሳ ኣለዎ ። ብሽክለታና ብሽክለታ ክትውፍዮ ትኽእል ኢኻ ፣ ካብ ካልእ ተጠቀምቲ ክትቅበል ትኽእል ኢኻ ፣ ካብ መድረኽ ክትረኽቦ ትኽእል ኢኻ ፣ ወይ ድማ ካብ ዝኾነ ናይ ገዛእ ርእስኻ ቦርሳ ክትእክብ ትኽእል ኢኻ — ንምጅማር ዝተፈለየ መተግበሪ ፣ ቅጥዒ ወይ ዘርኢ ኣየድልዮን እዩ ። ሚዛን ፣ ምኽርታት ፣ ምኽርታትን ዓስቢታትን ኩሎም ኣብ DeHub ምልክታት ይቐርቡ ፣ ስለዚ ዋጋ ብቐጥታ ኣብ መንጎ ተጠቀምቲ ይንቀሳቐስ ፣ ኣብ ክንዲ ብማእከላይ ናይ ክፍሊት ፕሮሰሰር ይንቀሳቐስ ፣ መለያ ክቐውም ይኽእል እዩ ።',
    howItWorksDesc2: 'እቲ መተግበሪ ንዓኻ ብኸመይ ከም ዚመላለስ እውን ይልውጥ እዩ ። ብዝያዳ DeHub ምልክታት ምስ እትሕዝ ፡ ነቲ ናይ መድረኽ ክፍሊትካ ብዝሓሸ መጠን ፡ ከምኡውን ነቲ እትኸፍትሉ ዓቕምኻ ብዝሓሸ መጠን — ባጅታት ፡ ምርግጋጽ ፡ ናይ ልማድ ምትብባዕ ፡ ናይ ክለብ ደረጃታት ፡ ከምኡውን ኣብ መላእ መርበብ ዝተመሓየሸ መሰላት ። ኣብ ግብሪ ምውዓል እቲ ምንዛሬ ቦልት-ኦን ኣይኮነን: እቲ ናይ ፍቓድ መስመር ፣ እቲ ሽልማት ባቡር ከምኡ\'ውን እቲ ቼክ ኣብ ሓደ እዋን እዩ ።',
