    pegDesc1: 'እቲ ናይ DeHub ምልክት ናይ ጥቕሚ ምልክት እዩ ። ንናይ ውሽጢ መተግበሪ ዕላማታት ኣብዚ እዋን እዚ ኣብ ሓደ ምልክት $ 0.001 ይቐርብ ፣ እዚ ድማ በቲ ናይ ፊያት ኣፍደገ ክትዕድግ ከለኻ እትርእዮ መጠን ከምኡ\'ውን ኣብ ውሽጢ መተግበሪ ዋጋታት ዚውዕል መጠን እዩ ። እዚ ፒግ እዚ ነቲ ኣብ ኣፕሊኬሽን ዘሎ ቁጠባ ኣብ እዋን እቲ መርበብ ክተተኣታተወሉ ዝኽእልን ክተተኣታተወሉ ዝኽእልን ክኸውን ይኽእል እዩ — እዚ ናይ ውሽጢ ሕሳብ መጠን እዩ እምበር ናይ መጻኢ ዋጋ መሬት ኣይኮነን ፣ ዋሕስ ወይ መብጽዓ ኣይኮነን ።',
