    howItWorksDesc2: 'እዚ ድማ ንብዘላ ስነ ምህዳር ጥራይ ዘይኰነስ ንብዘላ ኣካል እውን ይጠቅም እዩ ። ፈጣራት ትሕዝቶ ፡ ሸማቾች ፡ ሓላቑን ኩባንያታትን ኣብ መድረኽ ዝእውጁ ፡ ዝያዳ ዓስቢ ይረኽቡ እዮም ።',
    howItWorksDesc3: 'እቲ ናይ ገንዘብ ሓበሬታ እቲ ኣዝዩ ረብሓ ዘለዎ እዩ ፣ ናትና ድማ ኣብ ሓደ ናይ ስርዓት ኣወሃሃሃዲታት ንተዓዘብቲ ንምምልካት ክጥቀሙሉ ዝኽእሉ ሓደ እዩ ። እዚ ዋላ\'ውን ክትገብሮ እትኽእል ነገር ኣይኮነን ፣ ምኽንያቱ ናይ ባንክ መግለጺታት ብሕታዊ ስለዝኾኑ ፣ እቲ ባንክ ግን ህዝባዊ እዩ ።',
    howItWorksDesc4: 'ኣብ ባሕሪ ንዝርከቡ ንኣሽቱ ዓሳታት ፍሉይ ቅናሾት ወይ ቅናሾት ብምምዝጋብ ፡ ዓሳታትን ዓበይቲ ወፃኢታትን ንምምልካት ፡ ኣብ መላእ ዓለም ብኸመይ ከም ዚሰርሕ ፡ ኣብ መላእ ዓለም ፡ ኣፕልቲስቲክስ ብኸመይ ከም ዚሰርሕ ኪገልጽ እዩ ። ስለምንታይ እዩ እዚ ዘይደሊ ፧',
    preventFraud: 'እዚ ንጭፍጨፋ ብኸመይ ይከላኸል ፧',
    preventFraudDesc1: 'እቲ ቦቲንግ ኣብ እዋን እቲ ንጥፈት ኣብ መስመር ክተኣታተወሉ እንከሎ ፡ ብቐሊሉ ሕማቕ ተዋሳእቲ ብምትእስሳር ፡ ኣብ መወዳእታ ድማ ነቲ ምሉእ መሰረት ተጠቃሚ ክዓጽዎ እንከሎ ፡ ትርፊ ኣይረክብን እዩ ። ኣወሃሃሃዲታት ዝለዓለ ደረጃታት ይጥቀሙ ፣ ኣብ ታሕተዋይ ክፋል ድማ ዝኾነ ዝተረፈ ምትላል ይተርፍ ። ብተወሳኺ ፡ እቲ ማእከላይነትና ንዘይሕጋዊ ንጥፈታት ንምፍላጥን ንምክልኻልን ዝያዳ ውጽኢታዊ ክኸውን ይኽእል እዩ ።',
    preventFraudDesc2: 'ብዛዕባ ናይ ኣፕል ኣታዊ ምክፍፋልና ዝያዳ ሓበሬታ እንተ ደሊኻ ፡ ነዚ ገመድ እዚን ኣብ ታሕቲ ዘሎ ጻዕዳ ወረቐትን ጠውቑ ። ብተወሳኺ ፡ ብዛዕባ ባህርያትን ዝቕጽል ሓበሬታን ናይ መወዳእታ ዜናታት ክትከታተሉና ርግጸኛታት ኩኑ ።',
    dashboardPreview: 'ቅድመ ምርኣይ ዳሽቦርድ ኣስተዋጽኦ',
