      'ናይ መርበብ መኽዘን (web repository) ብ MIT ፍቓድ ህዝባዊ ኮይኑ — ነፍሲ ወከፍ መስመር ናይቲ ኣፕ ብግልጺ ይወጽእ ✅',
      'መድረኻት (Stages) ካብ ቀጥታ ናይ ድምጺ ክፍሊ ናብ ናይ ምዝርጋሕ መሳርሒ (broadcast stack) ዓብዩ፦ መደብ ምውጻእ፣ መዘኻኸሪታት፣ ሓጸርቲ ናይ ዕድመ ሊንክታት፣ ብዘይ OBS ብራውዘር ቀጥታ ምኻድ፣ ስክሪን ሼር፣ ናይ ተዓዘብቲ ቻትን ማዕጾ ከይተኸፍተ ቀጥታ ህዝቢ ✅',
