      'ፈጣሪዎች በደርዘን የሚቆጠሩ አዳዲስ የምስል እና የቪዲዮ ሞዴሎች፣ በመቶዎች የሚቆጠሩ ቅድመ-ቅምጦች (presets) ጨምሮ 180 የማቦሮሺ (Maboroshi) ቅድመ-ቅምጦች፣ የማቦሮሺ ቪዲዮ መተኪያ፣ የቫይራል ተፅእኖዎች፣ የገጸ-ባህሪ አብነቶች እና የሞሽን ክሊፕ ቤተ-መጽሐፍት አግኝተዋል ✅',
