    a14: 'እቲ ረብሓታት ንተመሓየሸ ባህርያት ፣ ዓለምለኻዊ ግብረ-ሰናይ ፣ ናይ ፈጣሪ ደረጃ ፣ ናይ NFT ዕዳጋ መግዛእቲ ፣ ናይ ምምሕዳር መሰላት ፣ ናይ ምቁራጽ ዓስቢ ፣ ናይ መርበብ ድሕነት ተሳትፎን ናይ መጻኢ ናይ ጥቕሚ ምዕባለን የጠቓልል ።',
