    prerequisites: 'እቲ ዘድልየካ',
    step1Desc: 'Dehub.io ክፉት ግበርን ጠውቑን ። ጉግል ፡ ኣፕል ፡ ቴሌግራም ፡ ኢመይል ፡ ኤስኤምኤስ ፡ ፓስኪ ወይ ቦርሳ ሕረጽ ። ኣብ ድሕረ ባይታ ዘይሕጋዊ ቦርሳ እዩ ተፈጢሩልካ — ነቲ ቁልፊ ትሕዝ — ጋዝ ድማ ትድግፎ ፣ ስለዚ ቅድሚ ምጅማርካ ገንዘብ ክትረክብ እትኽእል ነገር የለን ።',
    step1Title: 'ሕሳብካ ፍጠር',
    step2Desc: 'ኣብ መገለጺ ኣቀማምጣ ፡ → ናይ ምርኣይ ስም ፡ ናይ ተጠቃሚ ስም ፡ ኣቫታር ፡ ምስሊ ፡ ባዮ ፡ ከምኡውን ካልኦት ማሕበራዊ መራኸቢታትካ ብምትእስሳር ፡ መገለጺኻ ምሉእ ትሕዝቶኻ የርኢ ። ኣብኡ ከለኻ → ኣብ ኣቃውማታት ኣርእስቲ ሕረዶ ፡ ኣብ ከባቢኻ ክትርአ እንተ ደሊኻ ድማ ነቲ ናይ ምምራጽ መራሒ ስጉምቲ ውሰድ ።',
    step2Title: 'መገለጺኻ ኣዳሉ',
    step4Desc: 'ነፍሲ ወከፍ ፖስት ኣብ DeHub ቶከንስ ክተኣታተወሉ ይኽእል ። ካብኡ ድማ ኣባልነት ክትሸይጥ ፡ ናይ ደሞዝ-እይታ ልኡኻት ክትሕተም ፡ ቀጥታዊ መልእኽትታት ብውሑድ ምኽሪ ክትውስን ፡ መደበር ክትከፍት ፡ ናይ ምትእስሳር ትሕዝቶኻ ክትካፈል ትኽእል ኢኻ ፡ ካብ ሰባት ክትረኽቦ ትኽእል ኢኻ ።',
    step5Desc: 'ናይ DeHub ምልክታት ካብ ክራብ ክሳብ ሜጋሎዶን ባጅ ይረክብ ። ባጅ ክፍሊትካ ይንኪ ፣ ናይ ፖስታ ድጎማኻ ይውስኽ ፣ SuperPowers ይኽፈት ፣ ኣብ ርእይቶታትካ ፣ ግብረመልስን ድምጽን ድማ ክብደት ይውስኽ ።',
    step6Desc: 'እቲ ቦርሳኻ DeHubን ካልኦት ምስጢራዊ ምልክታትን ኣብ ዝተፈላለዩ ሰንሰለታት ይሕዝ ። ካብ 0.50 $ ብካርድ ወይ ብክሪፕቶ ምልክታት ግዛ ፣ ናብ ዝኾነ ሰብ ብነጻ ልኢኽዎም ፣ ኣብ ናይ DeHub ልውውጥ ንግዲ ፣ ከምኡ\'ውን ናብ ባጅ መሰላል ንምኻድ ኣክሲዮን ልኢኽዎም ።',
    step6Title: 'ነቲ ቦርሳኻ ተጠቐመሉ',
